#!/bin/bash
# Flash a built orin-steamos tree to a Jetson Orin Nano dev kit (NVMe) from an x86_64
# Linux host of any Ubuntu version, using NVIDIA's l4t_initrd_flash.sh inside an
# Ubuntu 22.04 container. WIPES the NVMe and rewrites the QSPI bootloader.
#
# usage: sudo ./flash.sh [--flash-only] [--erase-all] [--yes]
#   --flash-only  reuse images generated by a previous run (tools/kernel_flash/images)
#   --erase-all   erase all storage first (NVIDIA Quick Start does this)
#   --yes         don't ask for confirmation
#
# Everything this automates was learned the hard way on the first flash (see FLASH.md):
#  1. NetworkManager must not manage the Jetson's USB network (udev NM_UNMANAGED rule),
#     or it wipes the fc00:1:1::1 address mid-flash.
#  2. Inside a --network host container, NVIDIA's script runs 'service nfs-kernel-server
#     restart' and rpcbind. That stops the host's kernel nfsd and starts a second
#     rpc.mountd with the container's (empty) exports, which refuses the device. We shim
#     those out in the container, kill any container rpc.mountd, and serve the images
#     directory from the HOST's NFS server, exported to the device's exact address.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=config.env
. "$HERE/config.env"
L4T="${L4T:-$HERE/work/Linux_for_Tegra}"
IMAGES="$L4T/tools/kernel_flash/images"
DEVICE_ADDR="fc00:1:1::2"            # NVIDIA initrd flash: host ::1, device ::2 on usb0
CONTAINER="${CONTAINER:-orin-steamos-flash}"
IMAGE="${FLASH_CONTAINER_IMAGE:-ubuntu:22.04}"
UDEV_RULE=/etc/udev/rules.d/99-jetson-nm-unmanaged.rules

flash_only=0; erase_all=0; yes=0
for a in "$@"; do
  case "$a" in
    --flash-only) flash_only=1 ;;
    --erase-all)  erase_all=1 ;;
    --yes|-y)     yes=1 ;;
    -h|--help)    sed -n '2,20p' "$0"; exit 0 ;;
    *) echo "unknown option $a" >&2; exit 2 ;;
  esac
done

log() { printf '\n==> %s\n' "$*"; }
die() { echo "ERROR: $*" >&2; exit 1; }

[[ $EUID -eq 0 ]] || die "run with sudo (needs docker, exportfs, modprobe, udev)"
[[ -x $L4T/tools/kernel_flash/l4t_initrd_flash.sh ]] || die "no flash tree at $L4T (run ./build.sh first, or set L4T=)"
command -v docker >/dev/null || die "docker not installed"
command -v exportfs >/dev/null || die "host NFS server missing: sudo apt install nfs-kernel-server"
(( flash_only == 0 )) || [[ -s $IMAGES/system.img || -n "$(ls -A "$IMAGES" 2>/dev/null)" ]] \
  || die "--flash-only but $IMAGES is empty; run without --flash-only first"

rec="$(lsusb 2>/dev/null | grep -oiE '0955:7[0-9a-f]{3}' | head -1 || true)"
[[ -n $rec ]] || die "no Jetson in Force Recovery (jumper FC REC-GND, USB-C to host, power on; lsusb shows 0955:7523)"
[[ ${rec,,} == 0955:7523 ]] || echo "warning: found $rec, expected 0955:7523 (Orin Nano 8GB). Continuing."

if (( ! yes )); then
  echo "This WIPES the NVMe on the Jetson ($rec) and rewrites its QSPI bootloader."
  read -r -p "Type 'flash' to continue: " ans; [[ $ans == flash ]] || die "aborted"
fi

mkdir -p "$HERE/output"
LOGF="$HERE/output/flash-$(date +%Y%m%d-%H%M%S).log"
exec > >(tee -a "$LOGF") 2>&1
echo "log: $LOGF"

log "host: keep NetworkManager off the Jetson USB network"
if [[ ! -f $UDEV_RULE ]]; then
  echo 'SUBSYSTEM=="net", ACTION=="add|change", ATTRS{idVendor}=="0955", ENV{NM_UNMANAGED}="1"' > "$UDEV_RULE"
  udevadm control --reload
  echo "installed $UDEV_RULE (remove it after flashing if you want NM to manage Jetson USB networking)"
fi

log "host: kernel modules, ModemManager, NFS server"
for m in nfsd rndis_host cdc_ether cdc_ncm; do modprobe "$m" || true; done
mm_was_active=0
if systemctl is-active -q ModemManager 2>/dev/null; then mm_was_active=1; systemctl stop ModemManager; fi
[[ "$(sysctl -n net.ipv6.conf.all.disable_ipv6)" == 0 ]] || die "IPv6 is disabled on this host; the USB flash link needs it"
systemctl start rpcbind nfs-server 2>/dev/null || systemctl start nfs-kernel-server
mkdir -p "$IMAGES"
EXPORT="[$DEVICE_ADDR]:$IMAGES"
exportfs -o rw,nohide,insecure,no_subtree_check,async,no_root_squash "$EXPORT"
exportfs -f
showmount -e localhost | grep -F "$IMAGES" || die "host NFS export of $IMAGES failed"

cleanup() {
  set +e
  docker rm -f "$CONTAINER" >/dev/null 2>&1
  exportfs -u "$EXPORT" 2>/dev/null && echo "removed NFS export $EXPORT"
  exportfs -f
  (( mm_was_active )) && systemctl start ModemManager
}
trap cleanup EXIT

args=(--external-device nvme0n1p1 -c tools/kernel_flash/flash_l4t_t234_nvme.xml --network usb0)
(( flash_only )) && args=(--flash-only "${args[@]}")
(( erase_all )) && args+=(--erase-all)
args+=("$BOARD" internal)

# Runs inside the container (bash -c). Kept as a single-quoted heredoc: no host expansion.
read -r -d '' INNER <<'IN' || true
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq && apt-get install -y -qq sudo lsb-release kmod procps >/dev/null
./tools/l4t_flash_prerequisites.sh
# The host serves the images over NFS; tell NVIDIA's script so (documented marker file).
mkdir -p /run/nvidia_initrd_flash && touch /run/nvidia_initrd_flash/docker_host_network
# Shadow-mountd fix: with --network host, an in-container 'service nfs-kernel-server
# restart' stops the host's nfsd threads and starts a container rpc.mountd that refuses
# the device. Make those calls no-ops here (/usr/local/sbin is first in PATH).
cat > /usr/local/sbin/service <<'S'
#!/bin/sh
case "$1" in nfs-kernel-server|rpcbind) echo "[orin-steamos] skipped 'service $*' (host NFS is used)"; exit 0 ;; esac
exec /usr/sbin/service "$@"
S
printf '#!/bin/sh\nexit 0\n' > /usr/local/sbin/rpcbind
chmod 755 /usr/local/sbin/service /usr/local/sbin/rpcbind
pkill -x rpc.mountd || true
# Belt and braces: if anything still starts a container mountd, kill it.
( while sleep 2; do pkill -x rpc.mountd && echo "[orin-steamos] killed container rpc.mountd"; done ) &
./tools/kernel_flash/l4t_initrd_flash.sh "$@"
IN

log "flash: $IMAGE container, l4t_initrd_flash.sh ${args[*]}"
docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
set +e
docker run --rm --name "$CONTAINER" --privileged --network host -e USER=root \
  -v /dev:/dev -v /run/udev:/run/udev:ro -v /lib/modules:/lib/modules:ro \
  -v "$L4T:$L4T" -w "$L4T" "$IMAGE" bash -c "$INNER" flash "${args[@]}"
rc=$?
set -e
if (( rc == 0 )) && grep -q 'Flash is successful' "$LOGF"; then
  log "Flash is successful. The board reboots into orin-steamos."
  echo "Remove the FC REC jumper so later power-ups boot normally."
  echo "SSH: ssh $STEAM_USER@$HOSTNAME_TARGET.local   (sudo password: output/SECRETS.txt)"
else
  die "flash failed (rc=$rc); full log: $LOGF and $L4T/initrdlog/"
fi
